_choice_class() {
    php -r 'foreach (array_merge(get_declared_classes(), get_declared_interfaces(), get_declared_traits()) as $name) { echo $name, "\n"; }'
}

_choice_extension() {
    php -r 'foreach (get_loaded_extensions() as $name) { echo $name, "\n"; }'
}

_choice_function() {
    php -r 'foreach (get_defined_functions() as $names) { foreach ($names as $name) { echo $name, "\n"; } }'
}

